INSERT INTO `mod_lore_codex_entry` (`ID`, `Kind`, `Zone`, `SortOrder`, `Faction`, `RequiredState`, `Title`, `Body`, `Sources`) VALUES
(3600, 0, 36, 0, 0, 0, 'Alterac Mountains', 'These cold peaks between Lordaeron and the Hillsbrad foothills were once a proud human kingdom. Alterac began as a city-state of the old Arathorian empire, but in the Second War its king, Aiden Perenolde, secretly struck a bargain with Orgrim Doomhammer and let the Horde march through his mountain passes unopposed. When the treason came to light, King Terenas marched into Alterac, declared martial law and deposed him. The kingdom never recovered. Today the Crushridge ogres squat in the ruined capital, while the Syndicate, a gang of thieves led by Alterac''s disgraced nobles under Aliden Perenolde, holds Strahnbrad and the Uplands and dreams of taking the land back. Darker masters steer the Syndicate in secret. On the shore of Lordamere Lake lies the crater left by Dalaran, its wizards still patrolling the ruins, and hidden in the eastern hills the assassins of Ravenholdt wage their own quiet war on the Syndicate. Yetis haunt the high caves, and both Southshore and Tarren Mill send agents north into the snow.', 'warcraft.wiki.gg/wiki/Kingdom_of_Alterac (Arathorian city-state, Perenolde''s pact with Doomhammer, Terenas martial law, Aliden founded the Syndicate); warcraft.wiki.gg/wiki/Alterac_Mountains (Crushridge in Alterac City, Syndicate in Strahnbrad); quest 505 description (Syndicate led by villainous nobles of fallen Alterac); quest 537 and page_text 248-259 (Argus Wake controls the Syndicate); quest 602 description (Dalaran crater); warcraft.wiki.gg/wiki/Ravenholdt (war on the Syndicate); DB spawns: yetis in Growless Cave and The Headland'),
(3601, 1, 36, 1, 0, 0, 'Sofera''s Naze and Corrahn''s Dagger', 'North and west of Tarren Mill, where the foothills climb into the mountains, the Syndicate keeps two rough camps at Sofera''s Naze and Corrahn''s Dagger. Footpads and thieves loiter about the tents, and a few drunkards among them sing the praises of Southshore stout. Papers left on the camp tables are worth reading: one lists black masks, paralytic poison, stolen guard uniforms and rations for twenty men, all for an important mission against Southshore, signed by a Baron V. Another, left with a dying henchman named Valik, orders him to guard a slave until it can be moved north, out of sight. Southshore''s new magistrate blames the Syndicate for his predecessor''s murder, and these camps are where he looked first.', 'quest 505 description (camps in Sofera''s Naze and Corrahn''s Dagger north and west of Tarren Mill; previous magistrate assassinated); page_text 371 (Foreboding Plans supply list, signed Baron V.); quests 510, 511 (started from Syndicate Documents gameobjects 1740, 186420); creature_text 2440 (Drunken Footpad on Southshore stout); DB spawns: Syndicate Footpad 2240, Thief 2241, Drunken Footpad 2440 in areas 1678 and 1679; page_text 249 (Syndicate Missive addressed to Valik: guard the slave, moving it north); quest 535 description (Valik injured and dying); DB spawn: Henchman Valik 2333 in area 1678'),
(3602, 1, 36, 2, 0, 0, 'Strahnbrad', 'Strahnbrad was a mountain village of Lordaeron, defended in the Third War by Uther and Prince Arthas when Blackrock orcs raided it for slaves to sacrifice. Many of its people died, and the rest are long gone. The Syndicate now uses the town as its main base, and spies, wizards and the mysterious shadow mages of the Argus Wake walk its streets. Southshore''s magistrate believes the gang''s noble leaders hide here among common cutthroats, betrayed only by the signet rings of Alterac they still wear. The gang keeps prisoners here too: the orc Gol''dir was held in chains in a locked room, while the jailor Borhuin kept the key.', 'warcraft.wiki.gg/wiki/Strahnbrad (Third War Blackrock raid, Uther and Arthas; Syndicate main base; Gol''dir in a town cell, upstairs in the inn pre-Cataclysm); quest 512 description (headquarters, nobles with signet rings); quest 503 reward text; creature_text 2316 (Borhuin has the key); DB spawns: Syndicate Spy 2242, Syndicate Wizard 2319, Argus Shadow Mage 2318, Gol''dir 2316, Jailor Borhuin 2431 in area 280'),
(3603, 1, 36, 3, 0, 0, 'The Headland', 'The Headland is a rugged spur of the mountains above the Hillsbrad foothills, riddled with caves where ferocious yetis den. In the Foothill Caverns here, the wizard Helcular raised two ceremonial pyres, the Flame of Azel and the Flame of Veraz, for the ritual that was meant to make him a lich, and their fires still burn. A mob from Southshore killed him before the work was done, and the yetis took over his lair. Mountain lions prowl the cliffs, and dwarves of the Stormpike clan keep a camp here on the road north.', 'quest 552 description (Helcular nearly a lich, lynch mob, yeti overtook his ritual lair); quest 553 description (Flame of Azel and Flame of Veraz in the Foothill Caverns); DB spawns: Flame of Azel 1768 and Flame of Veraz 1769 in area 1680; Cave Yeti 2248, Ferocious Yeti 2249; Lieutenant Haggerdin 13841, Prospector Stonehewer 13816, Thanthaldis Snowgleam 13217 in area 1680; creature_loot_template: Helcular''s Rod 3708 drops from yetis; warcraft.wiki.gg/wiki/Helcular'),
(3604, 1, 36, 4, 0, 0, 'Growless Cave', 'High in the mountains above the Foothill Caverns, Growless Cave is a den of mountain yetis and the giants of their kind. Helcular built the third of his pyres here, the Flame of Uzel, and its fire still burns in the cold. Hunters who know the old lore use it as a lure: meat burned on the flame draws Frostmaw, an elusive yeti whose white coat hides him against the snow. During the Feast of Winter Veil the cave gains a stranger tenant, a creature called the Abominable Greench, who steals holiday treats and leaves those who cross him frozen into snowmen.', 'quest 553 description (Flame of Uzel in a cave above the caverns, further north); quest 1136 description (Frostmaw, white coat, lured with a scroll); warcraft.wiki.gg/wiki/Growless_Cave (yeti, Flame of Uzel, Frostmaw lured by burning meat); quests 6983, 7043 descriptions (Greench stole the treats, turned the speaker into a snowy mess); DB spawns: Mountain Yeti 2250, Giant Yeti 2251, Flame of Uzel 1770, The Abominable Greench 13602, Strange Snowman 13636 in area 1683'),
(3605, 1, 36, 5, 0, 0, 'Ruins of Alterac', 'The capital of Alterac was emptied when the kingdom fell, and after the Third War its deserted halls were claimed by the Crushridge ogres. Their warlord Mug''thol rules from the ruins of the old palace, with warmongers, maulers and ogre mages filling the broken streets. Among them wanders Grel''borg the Miser, a greedy ogre mage who spends his days digging through the rubble for baubles; rumor says he found the Perenolde Tiara, an heirloom of the old royal family crafted by Ironforge jewelers and set with emeralds. Wrecked meat wagons near the northern gate hint that the undead once tried to storm the place.', 'warcraft.wiki.gg/wiki/Ruins_of_Alterac (deserted ruins taken by Crushridge under Mug''thol after the Third War; meat wagons near the northern gate); warcraft.wiki.gg/wiki/Mug''thol (based in the ruins of the old palace); quest 543 description (Perenolde Tiara, Ironforge jewelers, emeralds, Grel''borg); page_text 372 (Grel''borg searching for baubles); quest 504 description; DB spawns: Crushridge Warmonger 2287, Mauler 2254, Enforcer 2256, Mage 2255, Mug''thol 2257, Grel''borg 2417 in area 281'),
(3606, 1, 36, 6, 0, 0, 'Crushridge Hold', 'Beside the ruined capital, the Crushridge ogres have dug an ogre mound of their own into the mountains. Crushridge Hold is their stronghold, crowded with ogres and brutes, and their camps spill out into Slaughter Hollow and along the old road at Gallows'' Corner, where they prowl around a ruined scout tower. The slopes here are rich in mithril and truesilver, and at least one bold trader in engineering supplies has set up shop in Slaughter Hollow. Southshore pays bounties on ogre knucklebones, fearing that if the Crushridge grow comfortable here they will move down into the foothills next.', 'quest 500 description (ogre mound near the ruined city; fear they will move into the foothills); warcraft.wiki.gg/wiki/Crushridge_clan (Crushridge Hold, Slaughter Hollow); warcraft.wiki.gg/wiki/Gallows''_Corner (crossroads near the ruins, ogres around a ruined scout tower); DB spawns: Crushridge Ogre 2252, Brute 2253 in areas 282, 283, 1357; Mithril and Truesilver Deposits; Rizz Loosebolt 2684 (Engineering Supplies) in area 283'),
(3607, 1, 36, 7, 0, 0, 'The Uplands', 'North of Strahnbrad lie the Uplands, the farmlands that once fed the kingdom of Alterac. Today this is where the Syndicate is strongest. Sentries and saboteurs guard its camps, the shadow mages of the Argus Wake come and go, and Baron Vardus, a cold-hearted Alterac noble wanted by both Southshore and the Forsaken, has been seen among them. Not every house here belongs to a thief. Beside the lake lives Nancy Vishas, whose husband serves the Scarlet Crusade as an interrogator, and who waits anxiously at home whenever his work at the Monastery keeps him late.', 'warcraft.wiki.gg/wiki/The_Uplands (bread basket of Alterac; Syndicate strongest); quest 537 description (Uplands where the Syndicate is strongest, north of Strahnbrad); quest 566 description (Vardus last spotted in the Uplands); quest 1051 description (Interrogator Vishas, wife Nancy along Lake Lordamere); creature_text 3984, 3985; DB spawns: Syndicate Sentry 2243, Saboteur 2245, Argus Shadow Mage 2318, Baron Vardus 2306, Nancy 3984, Grandpa Vishas 3985 in area 284'),
(3608, 1, 36, 8, 0, 0, 'Dandred''s Fold', 'On the western edge of the Uplands, a farm and manor house look down on a small harbor on Lordamere Lake, near the Misty Shore. This is Dandred''s Fold, the residence of Lord Aliden Perenolde, who styles himself lord of these lands and runs the Syndicate from here. Its grounds are guarded by the gang''s assassins and enforcers. Within the manor, Perenolde keeps his mistress Elysa, and he meets here with Nagaz of the Argus Wake, the hidden power whose hand guides the Syndicate''s ambitions. Snapping turtles crawl along the misty lakeshore below.', 'warcraft.wiki.gg/wiki/Dandred''s_Fold (farm and manor on the westernmost Uplands, harbor on Lordamere Lake, Misty Shore; Perenolde, Elysa, Nagaz, assassins and enforcers); quest 506 description (styled himself lord of this land); quest 507 description (manor on the shores of Lordamere Lake); DB spawns: Lord Aliden Perenolde 2423, Elysa 2317, Nagaz 2320 side by side; Syndicate Assassin 2246, Enforcer 2247; Snapjaw 2408 in areas 1682 and 1681'),
(3609, 1, 36, 9, 0, 0, 'Lordamere Internment Camp', 'On a hill above the crater of Dalaran stands the Lordamere Internment Camp, the only prison camp in the mountains, held by Dalaran''s shield guards and theurgists under Warden Belamoore. Its newest inmates are four Forsaken who deserted the Undercity after breaking into a secure vault and stealing four artifacts, pieces of bloodstone the royal apothecaries needed for their studies. The thieves fled to Dalaran, and the wizards quarantined them here. The Dark Lady wants her property returned and the deserters punished.', 'warcraft.wiki.gg/wiki/Lordamere_Internment_Camp (only internment camp in the mountains, hill overlooking the crater, Dalaranian forces, Warden Belamoore, four Forsaken deserters); quest 544 description and reward text; items 3688-3691 Bloodstone Oval, Marble, Shard, Wedge dropped by Kegan Darkmar 2414, Ricter 2411, Alina 2412, Dermot 2413; DB spawns: Dalaran Shield Guard 2271, Theurgist 2272, Warden Belamoore 2415 in area 278'),
(3610, 1, 36, 10, 0, 0, 'Dalaran Crater', 'Dalaran, city of the Kirin Tor, was laid waste in the Third War when the Burning Legion''s Archimonde was summoned before its walls. The wizards later raised a vast violet dome over the heart of their ruins and rebuilt behind it, and in time they lifted their reborn city whole into the skies of Northrend. All that remains on the shore of Lordamere Lake is a gaping crater beneath a dome now faded nearly to nothing, ringed by broken walls. Some mages stayed behind. Summoners and their bound earth elementals still patrol the ruined outskirts, workers labor in the rubble, and a few archmages keep watch over what is left.', 'warcraft.wiki.gg/wiki/Dalaran_Crater (Wrath: city lifted to Northrend leaving a gaping crater; dome remains, nearly transparent); warcraft.wiki.gg/wiki/Alterac_Mountains (Archimonde destroyed Dalaran); quest 545 description (vast magical dome, ruined outskirts patrolled by wizards and elemental slaves); quest 602 description (rebuilt and moved to Northrend, massive crater; some mages remained); quest 557 (Bracers of Earth Binding); creature_text 2359 (elemental slave cracks, rubble); DB spawns: Dalaran Summoner 2358, Elemental Slave 2359, Dalaran Worker 2628, Ansirem 2543, Archmage Cedric 18165 in area 279'),
(3611, 1, 36, 11, 0, 0, 'Ravenholdt Manor', 'Hidden in the eastern hills above Hillsbrad, at the end of a winding mountain path northwest of Durnholde, stands Ravenholdt Manor, seat of the Assassin''s League. Outsiders are not welcome. The guards greet strangers with a warning to watch their backs, and the assassins on the grounds are quicker still to show their contempt. Within, Lord Jorach Ravenholdt presides over a guild of thieves and killers that admits only the most gifted. The manor has its own poison seller, a specialist engineer, a garden kept by a landscape architect, and a training arena that is the domain of the orc Master Kang. Its long war is with the Syndicate.', 'warcraft.wiki.gg/wiki/Ravenholdt_Manor (eastern Alterac, path northwest of Durnholde through a small cave; Simone Cantrell''s garden; Master Kang, orc, training arena); warcraft.wiki.gg/wiki/Ravenholdt (Assassin''s League, only those of extraordinary prowess, outsiders not welcome, conflict with the Syndicate); quest 8233 description (path in the mountains northwest of Durnholde); npc_text for gossip menus 4861, 4862 (Watch your back, stranger; You dare set foot inside Ravenholdt Manor, worm?); creature_template subnames: Smudge Thunderwood 6779 Poison Supplies, Zan Shivsproket 6777 Speciality Engineer, Simone Cantrell 7324 Landscape Architect; DB spawn: Master Kang 7325 in area 3486'),
(3612, 1, 36, 12, 0, 0, 'Chillwind Point', 'On the far eastern edge of the mountains, beside the river that runs north past Tarren Mill, a small rise is crowned by the ruins of an ancient troll site. Chill winds sweep down through a nearby ravine from the Plaguelands to the north, and give the point its name. Here the jungle troll hermit Bath''rah the Windwatcher keeps his camp and his cauldron, watching the ruins for a great elemental lord of the winds he calls Cyclonian. A red drake, Narillasanz, is sometimes seen in these eastern heights.', 'warcraft.wiki.gg/wiki/Chillwind_Point (small rise on the far eastern edge, ancient troll ruin, named for chill winds from the Western Plaguelands, Bath''rah); quest 1791 description (river along Tarren Mill''s eastern flank, ruins on its eastern bank); quest 1712 description (watching this site for Cyclonian, the wind lord); warcraft.wiki.gg/wiki/Narillasanz (red drake in the Alterac Mountains); DB spawns: Bath''rah 6176, Bath''rah''s Cauldron 89931, Narillasanz 2447 in area 1684'),
(3613, 2, 36, 1, 0, 0, 'Lord Aliden Perenolde', 'Aliden is the eldest son of Aiden Perenolde, the king who sold out the Alliance to the Horde. For two years after the Second War he tried to wash that stain from the family name, rising through the ranks at Durnholde under his mentor Aedelas Blackmoore. Then he left Blackmoore''s service for the mountains of Alterac and founded the Syndicate. From his manor at Dandred''s Fold he styles himself lord of the land, and he means to enslave the orcs who stand against him, just as his father and Blackmoore once planned. Nagaz of the Argus Wake keeps close at his side, and his young mistress Elysa wore a pendant the Warchief himself wanted back.', 'warcraft.wiki.gg/wiki/Aliden_Perenolde (eldest son of Aiden; two years clearing the name; Durnholde under Blackmoore; left to run operations in Alterac); warcraft.wiki.gg/wiki/Kingdom_of_Alterac (Aliden founded the Syndicate); quest 506 description (styled himself lord, plans to enslave orcs like his father and Blackmoore, mistress Elysa, pendant); quest 507 description; warcraft.wiki.gg/wiki/Nagaz (positioned himself close to Perenolde)'),
(3614, 2, 36, 2, 0, 0, 'Mug''thol', 'Mug''thol is warlord of the Crushridge ogres and master of the ruined city of Alterac. He rules from what is left of the old palace, with his loyal lieutenants Targ, Muckrake and Glommus at his side and the greedy ogre mage Grel''borg the Miser among his followers. He was not always his own master. The Banshee Queen once bound him to her will through a banshee''s possession and sent him into Alterac after a relic, the Crown of Will. He put the crown on, and it set him free. The Forsaken have not forgiven the insult, and Southshore fears his ogres will push down into the foothills next.', 'quest 495 description (sent to retrieve the Crown of Will, tried it on, resisted the possession); warcraft.wiki.gg/wiki/Mug''thol (possessed by a banshee sister, old palace, lieutenants, founded the Crushridge in the ruins); quest 519 description (Targ, Muckrake, Glommus loyal lieutenants); quest 520 description; quest 500 description (fear the ogres will move into the foothills)'),
(3615, 2, 36, 3, 2, 0, 'Gol''dir', 'Gol''dir led the band of orc warriors the Warchief sent from Durotar to look into the Syndicate and to recover a small trinket Thrall wanted back. The humans overwhelmed them at Durnholde, and Gol''dir was carried off and moved from place to place until the Syndicate chained him in Strahnbrad. His captors set him to hauling burdens and digging, and the jailor Borhuin kept the key to his chains. There Aliden Perenolde himself came to boast of his plans to enslave the orcs, bringing along a mistress who wore the very pendant the Warchief sought. Gol''dir counts his own suffering as unimportant: what matters is that his people learn what he heard.', 'quest 498 description and reward text (expedition, Durnholde, Gol''dir taken elsewhere); quest 533 description (humans moving him around); quest 503 reward text (led the expedition from Durotar, forced to work hauling and digging); quest 506 description (Perenolde''s visit and plans); creature_text 2316; item 3704 Rusted Iron Key from Jailor Borhuin 2431'),
(3616, 2, 36, 4, 0, 0, 'Baron Vardus', 'Baron Vardus is a noble of fallen Alterac, known for his cold heart and brutal methods, and a high-ranking member of the Syndicate. A supply list for a raid on Southshore bears the signature of a Baron V., the gang''s quartermaster, and a contract for the murder of Magistrate Henry Maleb, sealed in red wax with a distinctive signet, was signed with his name. That was enough for Southshore to demand his head. The Forsaken want him dead as well, for crimes against them, and High Executor Darthalia of Tarren Mill has posted a bounty. He was last seen in the Uplands.', 'quest 523 description (noble of Alterac, cold heart, brutal practices, signed the contract); quest 522 description (sealed with red wax and a distinctive signet ring); page_text 371 (signed Baron V.); quest 566 description (crimes against the Forsaken, high-ranking member, Uplands); warcraft.wiki.gg/wiki/Syndicate (high-ranking member); warcraft.wiki.gg/wiki/Baron_Vardus (Syndicate quartermaster, citing Foreboding Plans)'),
(3617, 2, 36, 5, 0, 0, 'Nagaz', 'Nagaz is a hierophant of the Argus Wake, the shadowy circle that quietly steers the Syndicate, and the hand of his master''s will in Alterac. He keeps close to Lord Perenolde at Dandred''s Fold. In a letter to that master, written in one of the Wake''s most obscure ciphers and signed in the name of Sargeras, he mocked the Alterac nobles for a bargain they would regret. He meant to steer them toward Stromgarde and so win the Wake a nation of its own, from which to prepare the way for the Third Host of the Burning Legion. Southshore wants his head, though its magistrate fears Nagaz is only a servant and the Wake runs far deeper.', 'page_text 248, 257, 258, 259 (Decrypted Letter); quest 537 description and reward text (Nagaz of the Argus Wake, servant of another); warcraft.wiki.gg/wiki/Argus_Wake (hierophant, controlled the Syndicate); DB spawn: Nagaz 2320 beside Perenolde 2423 in Dandred''s Fold; page_text 315 (signed Nagaz, Argus Heirophant, in Sargeras'' name; master appointed head of the Argus Wake by the Council); quest 537 reward text (merely the servant of another; may run deep); quest 551 (Ensorcelled Parchment bearing his name, from Worn Wooden Chest 1765 beside Nagaz in Dandred''s Fold)'),
(3618, 2, 36, 6, 0, 0, 'Lord Jorach Ravenholdt', 'Lord Jorach Ravenholdt is master of the Assassin''s League, the order of thieves and killers that gathers at Ravenholdt Manor. After the Third War he took up the hunt for the Syndicate in these mountains, and the League has fought the gang ever since. With far fewer blades than their enemy has members, the League pays skilled rogues to shame Syndicate members by stealing their emblems. His grand master, Fahrad, trains the guild''s rogues and sends anyone else away with a threat. Jorach greets those he needs with open arms and rewards loyal service generously, but keeps his own secrets close: the contents of a sealed azure bag he once lost were, he said, a private matter.', 'warcraft.wiki.gg/wiki/Jorach_Ravenholdt (leader of the League, hunted the Syndicate after the Third War, Sealed Azure Bag); warcraft.wiki.gg/wiki/Ravenholdt (outnumbered by the Syndicate, emblems stolen to shame members); quest 6701 (Syndicate Emblems); quests 8233, 8234, 8236 (welcome, private matter, golden glow from the bag); npc_text 4838, 4839 (Fahrad gossip menu 3984); quest 6701 starts from Ravenholdt Guard 6766'),
(3619, 2, 36, 7, 1, 0, 'Archmage Ansirem Runeweaver', 'Ansirem Runeweaver is a senior archmage of the Kirin Tor, and by the Third War sat on the Council of Six. When Antonidas fell he fought outside the walls of Dalaran against Arthas and the Scourge while Kel''Thuzad called down Archimonde. Now that Dalaran has risen to Northrend, he is among the few mages who stayed at the crater. His learning ranges far: years ago he wrote a tome on the legends of the Gurubashi Empire, and he cannot resist a magical puzzle. His willful daughter Catelyn gave up the mage''s life and ran off to Booty Bay to become a pirate.', 'warcraft.wiki.gg/wiki/Ansirem_Runeweaver (Kirin Tor, Council of Six, fought outside Dalaran while Kel''Thuzad summoned Archimonde); quest 602 description and reward text (some mages remained; tome on the Gurubashi Empire; mages cannot resist a magical puzzle); quest 603 description (willful daughter Catelyn ran off to Booty Bay to be a pirate); creature_text 2543'),
(3620, 2, 36, 8, 0, 0, 'Archmage Cedric', 'Archmage Cedric is an agent of the Violet Eye, the order the Kirin Tor assigned to watch over Karazhan and Medivh. He waits among the ruins at the edge of Dalaran Crater, unmoved by the desolation around him and certain that Dalaran is as powerful as ever. When Archmage Alturus sent word of a demonic presence stirring in the sealed tower, it was Cedric who read the report and sent it on to Shattrath, to Khadgar, the one man still living who was thought able to open Karazhan again. Those who help the Violet Eye may earn its trust, and its badge.', 'quest 9826 description (Violet Eye, agents of the Kirin Tor watching Karazhan; Cedric in the outskirts of Dalaran Crater); quest 9829 description (demonic emanation, Khadgar in Shattrath); quest 9860 description and reward text (badge of the Violet Eye); npc_text for gossip menu 7593 (Dalaran is as powerful as ever)'),
(3621, 2, 36, 9, 0, 0, 'Bath''rah the Windwatcher', 'Bath''rah is a jungle troll shaman and weaponcrafter who has taken up a hermit''s life at the troll ruins of Chillwind Point. For ages, he says, he has watched the site, waiting for a champion able to bring down Cyclonian, the lord of the winds who can be called there. Those who gather what his summoning needs may face the elemental, and from its whirlwind heart Bath''rah will forge a weapon. Lately the spirits of the place have turned against him, and he has sought a spirit totem, strengthened with troll voodoo, to guard his sleep.', 'warcraft.wiki.gg/wiki/Bath''rah_the_Windwatcher (jungle troll, weaponcrafter turned hermit, Chillwind Point); quest 1791 description (skilled weapon maker and powerful shaman); quests 1712, 1713, 1792 (Cyclonian, whirlwind heart, weapon); quests 8412, 8413 (spirits no longer like him, spirit totem, voodoo, a full night''s rest)'),
(3622, 2, 36, 10, 0, 0, 'Nancy Vishas', 'Nancy Vishas lives in a house in the Uplands near Lake Lordamere, where she waits anxiously for her husband to come home from his work at the Monastery. Her husband is the Scarlet Crusade''s Interrogator Vishas, and his work is torture. One of his victims, the Forsaken Vorrel Sengutz, was held and tormented for weeks, and saw his own wedding ring taken and given to Nancy. Vorrel''s dying wish was that she be found and slain, and the ring returned to his widow Monika in Tarren Mill. An old man called Grandpa Vishas shares the house and has no patience for her fretting.', 'quest 1051 description and reward text; creature_text 3984 (Sidney is late, work at the Monastery), 3985 (He''s your husband, woman); DB spawns: Nancy Vishas 3984 and Grandpa Vishas 3985 in area 284; Monika Sengutz 3982 in Tarren Mill; warcraft.wiki.gg/wiki/Interrogator_Vishas (wife Nancy, cottage on Lordamere Lake)'),
(3627, 3, 36, 5, 2, 0, 'The Bloodstone Thieves', 'Some months ago four Forsaken deserted the Undercity, and before they fled they broke into a secure vault and stole four artifacts the royal apothecaries needed for their studies. They ran to Dalaran, and the wizards locked them away in the Lordamere Internment Camp. Magus Wordeen Voidglare, who had come to Tarren Mill only to research, found himself charged with getting the artifacts back for the Dark Lady and seeing the deserters, Kegan Darkmar among them, brought to justice. The Magus has his own interests too. He has the patrols of summoners and elemental slaves around Dalaran thinned so that the ruins can be searched for magical treasures, and Keeper Bel''varil, who serves him, collects the stone tokens the wizards use to command their elementals, and the binding bracers set on the elementals themselves, for the Magus to study.', 'quests 544, 545, 556, 557 (descriptions and reward texts); creature_queststarter: Magus Wordeen Voidglare 2410 starts 544, 545; Keeper Bel''varil 2437 starts 556, 557');
